#!/usr/bin/env node
// Shim that delegates to the platform-specific binary provided by optionalDependencies.
'use strict';

const path = require('path');
const { spawnSync } = require('child_process');

const PLATFORMS = {
  'darwin-x64':   '@zread/cli-darwin-x64',
  'darwin-arm64': '@zread/cli-darwin-arm64',
  'linux-x64':    '@zread/cli-linux-x64',
  'linux-arm64':  '@zread/cli-linux-arm64',
  'win32-x64':    '@zread/cli-win32-x64',
  'win32-arm64':  '@zread/cli-win32-arm64',
};

const key = `${process.platform}-${process.arch}`;
const pkg = PLATFORMS[key];
if (!pkg) {
  console.error(`[zread] Unsupported platform: ${key}`);
  process.exit(1);
}

let pkgDir;
try {
  pkgDir = path.dirname(require.resolve(`${pkg}/package.json`));
} catch {
  console.error(`[zread] Platform package ${pkg} not found. Try reinstalling: npm install -g zread_cli`);
  process.exit(1);
}

const isWindows = process.platform === 'win32';
const binPath = path.join(pkgDir, isWindows ? 'zread.exe' : 'zread');

const result = spawnSync(binPath, process.argv.slice(2), { stdio: 'inherit' });
process.exit(result.status ?? 1);
